// Общие шаги блока «עסקים נוספים שעשויים לעניין אותך» (#02706d). Прод — только просмотр:
// страница объявления шлёт POST increment_business_views, поэтому все не-GET запросы окна блокируются.
// Объявления не хардкодятся: берутся из кэша активных объявлений сайта в localStorage.
import { expect, Page } from '@playwright/test';

export const BLOCK_TITLE = 'עסקים נוספים שעשויים לעניין אותך';
export const HISTORY_KEY = 'b4s_viewed_categories';
const CACHE_KEY = 'biz4sale_active_businesses_cache:-created_date';
const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];
const LOAD = { timeout: 20_000 };

export type Biz = { id: string; category: string | null; city: string | null; description: string | null; status: string };

/** Блокирует все записи (не-GET) во всём окне — до первого перехода. */
export async function blockWrites(page: Page) {
  await page.context().route('**/*', (route) =>
    SAFE_METHODS.includes(route.request().method()) ? route.fallback() : route.abort('blockedbyclient'),
  );
}

export function block(page: Page) {
  return page.getByRole('heading', { name: BLOCK_TITLE }).locator('xpath=..');
}

/** Открыть объявление и дождаться карточек в блоке. */
export async function openListing(page: Page, id: string) {
  await page.goto(`/businessdetail?id=${id}`);
  await expect(page.getByRole('heading', { name: BLOCK_TITLE })).toBeVisible(LOAD);
  await expect(block(page).locator('a[href*="source=similar_businesses"]').first()).toBeAttached(LOAD);
}

/** id карточек блока в порядке показа. */
export async function cardIds(page: Page): Promise<string[]> {
  const ids = await block(page)
    .locator('a[href*="source=similar_businesses"]')
    .evaluateAll((as) => as.map((a) => new URL((a as HTMLAnchorElement).href).searchParams.get('id') || ''));
  return [...new Set(ids)];
}

export async function viewedCategories(page: Page): Promise<string[]> {
  const raw = await page.evaluate((k) => localStorage.getItem(k), HISTORY_KEY);
  expect(raw, `localStorage «${HISTORY_KEY}» записан`).not.toBeNull();
  return JSON.parse(raw!);
}

/** Каталог активных объявлений — из кэша сайта (появляется после загрузки любой страницы с объявлениями). */
export async function readCatalog(page: Page): Promise<Biz[]> {
  await expect.poll(() => page.evaluate((k) => !!localStorage.getItem(k), CACHE_KEY), LOAD).toBe(true);
  const raw = await page.evaluate((k) => localStorage.getItem(k)!, CACHE_KEY);
  return (JSON.parse(raw).data as Biz[]).filter((b) => b.status === 'פעיל');
}

function countBy<T>(items: T[], key: (t: T) => string | null) {
  const m = new Map<string, number>();
  for (const it of items) {
    const k = key(it);
    if (k) m.set(k, (m.get(k) || 0) + 1);
  }
  return m;
}

/** Город однозначный: заполнен и нет другого написания, содержащего его (например «תל אביב» / «תל אביב-יפו»). */
export function cityIsUnambiguous(catalog: Biz[], city: string | null) {
  if (!city) return false;
  const cities = new Set(catalog.map((b) => b.city).filter(Boolean) as string[]);
  return [...cities].every((c) => c === city || (!c.includes(city) && !city.includes(c)));
}

/** Маленькие категории (2–5 активных объявлений), от меньшей к большей. */
export function smallCategories(catalog: Biz[]) {
  const counts = countBy(catalog, (b) => b.category);
  return [...counts.entries()].filter(([, n]) => n >= 2 && n <= 5).sort((a, b) => a[1] - b[1]);
}

/**
 * Маршрут из 3 маленьких категорий A → B → C (вместе ≤ 13 объявлений, чтобы в 12 карточках были видны и B, и A);
 * у последнего объявления (C) город однозначный.
 */
export function pickRoute(catalog: Biz[]): Biz[] {
  const cats = smallCategories(catalog);
  for (const [c] of cats) {
    const last = catalog.find((b) => b.category === c && cityIsUnambiguous(catalog, b.city));
    if (!last) continue;
    const others = cats.filter(([k]) => k !== c);
    for (let i = 0; i < others.length; i++)
      for (let j = i + 1; j < others.length; j++) {
        const [b, nb] = others[i];
        const [a, na] = others[j];
        const nc = cats.find(([k]) => k === c)![1];
        if (nc - 1 + nb + na <= 12)
          return [catalog.find((x) => x.category === a)!, catalog.find((x) => x.category === b)!, last];
      }
  }
  throw new Error('В каталоге нет 3 маленьких категорий для маршрута — данные сайта, не баг');
}

/**
 * Проверка порядка блока: та же категория (0) → недавние категории, новая первой (1..n) → тот же город (100) → остальные (200).
 * Ранги не убывают, и если видна группа ниже — группа выше показана целиком (кроме текущего объявления).
 */
export function expectOrder(catalog: Biz[], current: Biz, history: string[], ids: string[]) {
  const byId = new Map(catalog.map((b) => [b.id, b]));
  const recent = history.filter((c) => c !== current.category);
  const rank = (b: Biz) =>
    b.category && b.category === current.category
      ? 0
      : b.category && recent.includes(b.category)
        ? 1 + recent.indexOf(b.category)
        : current.city && b.city === current.city
          ? 100
          : 200;
  expect(ids, 'текущего объявления в блоке нет').not.toContain(current.id);
  expect(ids.length, 'в блоке есть карточки (до 12)').toBeGreaterThan(0);
  expect(ids.length).toBeLessThanOrEqual(12);
  const shown = ids.map((id) => {
    const b = byId.get(id);
    expect(b, `карточка ${id} — активное объявление из каталога`).toBeTruthy();
    return b!;
  });
  const ranks = shown.map(rank);
  const describe = shown.map((b, i) => `${ranks[i]}:${b.category || '—'}/${b.city || '—'}`).join(' · ');
  for (let i = 1; i < ranks.length; i++)
    expect(ranks[i], `порядок групп не нарушен (ранг: категория/город): ${describe}`).toBeGreaterThanOrEqual(ranks[i - 1]);
  const maxRank = Math.max(...ranks);
  const missing = catalog.filter((b) => b.id !== current.id && rank(b) < maxRank && !ids.includes(b.id));
  expect(
    missing.map((b) => `${rank(b)}:${b.category}/${b.city}`),
    `группы выше последней показанной — целиком: ${describe}`,
  ).toEqual([]);
  return ranks;
}
